package en16931

import (
	"embed"
	"fmt"
	"sync"

	"github.com/dcnws/invoicekit.go/internal/xp"
	"github.com/dcnws/invoicekit.go/internal/xsd"
)

// The pruned XML schema models for the two syntaxes, generated by cmd/xsdgen
// from the official UN/CEFACT and OASIS schema trees and gzipped: the raw
// schemas are 2.9 MB, the models actually reachable from an invoice are a
// fraction of that.
//
//go:embed schemas/cii-xsd.xml.gz schemas/ubl-xsd.xml.gz
var xsdFS embed.FS

// xsdFile maps a syntax to its embedded schema model.
var xsdFile = map[Syntax]string{
	SyntaxCII: "schemas/cii-xsd.xml.gz",
	SyntaxUBL: "schemas/ubl-xsd.xml.gz",
}

var (
	xsdMu    sync.Mutex
	xsdCache = map[Syntax]*xsd.Model{}
)

// SchemaModel returns the parsed XML schema model for a syntax, cached. It
// describes the element structure the syntax allows: names, cardinality and
// child order. The Schematron rule sets check presence and counts only, so this
// is what catches a misplaced or unexpected element.
func SchemaModel(sx Syntax) (*xsd.Model, error) {
	xsdMu.Lock()
	defer xsdMu.Unlock()
	if m, ok := xsdCache[sx]; ok {
		return m, nil
	}
	name, ok := xsdFile[sx]
	if !ok {
		return nil, fmt.Errorf("en16931: unknown syntax %q (want CII or UBL)", sx)
	}
	raw, err := xsdFS.ReadFile(name)
	if err != nil {
		return nil, err
	}
	src, err := gunzip(name, raw)
	if err != nil {
		return nil, fmt.Errorf("en16931: %s schema model: %w", sx, err)
	}
	// The generated model is self-contained: no imports, no includes.
	m, err := xsd.Load(name, src, nil)
	if err != nil {
		return nil, fmt.Errorf("en16931: %s schema model: %w", sx, err)
	}
	xsdCache[sx] = m
	return m, nil
}

// SchemaFindings checks a parsed document against the schema model of a syntax.
// An empty result means the document's structure is what its schema allows.
func SchemaFindings(sx Syntax, doc *xp.Doc) ([]xsd.Finding, error) {
	m, err := SchemaModel(sx)
	if err != nil {
		return nil, err
	}
	return m.Validate(doc), nil
}
